{% include 'Elements.xml' %}
{% include 'Custom Config.xml' %}
{% for system in g.data.get("systems", []) %}
  {% include 'Systems (Generated)/' + system + '.xml' %}
{% endfor %}
{% for module in g.data.get("scripts", []) %}
  {% include 'Custom Scripts/' + module + '.xml' %}
{% endfor %}
